/**
 * Owns Fragrant's per-execution night acquisition, publication and terminal close.
 * Inputs are delegated original World/events, the same day/currentness and a lazy
 * knowledge-draw factory; writes retain original authority and publication order.
 * Only an acquired, not normally closed unit attempts abort. Failed opening or
 * publication preserves its existing committed prefix; closure never redraws or
 * refunds paid bindings. Authority retains roster, choices and relationship ownership.
 */
import type { World } from "../../../../core/domain/world";
import type { GameEvent } from "@ai-werewolf-arena/game-contract";
import type { RandomDraws } from "../../../../core/domain/random";
import { Role } from "@ai-werewolf-arena/game-contract";
import { beginFragrantNight, closeFragrantNight, fragrantAuthoritySnapshot } from "./authority";
import { FRAGRANT_PAIR_POLICY } from "./state";

export interface FragrantNightRuntime {
  readonly world: World;
  readonly events: GameEvent[];
  drawKnowledge(): RandomDraws;
  recordOpening(day: number, notice: ReturnType<typeof beginFragrantNight>): void;
}

export class FragrantNightUnit {
  private acquired = false;
  private closed = false;
  constructor(
    private readonly runtime: FragrantNightRuntime,
    private readonly day: number,
  ) {}
  open(isCurrent: () => boolean): void {
    const ctx = this.runtime,
      day = this.day;
    const before = fragrantAuthoritySnapshot(ctx.world),
      notice = beginFragrantNight(ctx.world, day, ctx.drawKnowledge(), isCurrent),
      after = fragrantAuthoritySnapshot(ctx.world);
    this.acquired = true;
    ctx.events.push({
      timestamp: Date.now(),
      type: "fragrant_night_opened",
      payload: {
        policy: FRAGRANT_PAIR_POLICY,
        actorId: after.phantomId,
        day,
        knowledgeDrawCount: day === 1 ? 1 : 0,
      },
      audience: Object.freeze([]),
    });
    for (const old of before.fragrant.bindings.filter((b) => b.status.kind === "pending")) {
      if (after.fragrant.bindings.find((b) => b.id === old.id)?.status.kind === "expired")
        ctx.events.push({
          timestamp: Date.now(),
          type: "fragrant_binding_expired",
          payload: {
            policy: FRAGRANT_PAIR_POLICY,
            actorId: ctx.world.getEntityIdsByRole(Role.FragrantPhantom)[0]!,
            day,
            bindingId: old.id,
            createdNight: old.createdNight,
            pairIds: old.pairIds,
          },
          audience: Object.freeze([]),
        });
    }
    if (notice)
      ctx.events.push({
        timestamp: Date.now(),
        type: "fragrant_night_notified",
        payload: { policy: FRAGRANT_PAIR_POLICY, ...notice },
        audience: Object.freeze([notice.actorId]),
      });
    ctx.recordOpening(day, notice);
  }
  closeNormally(): void {
    closeFragrantNight(this.runtime.world, this.day, "normal");
    this.closed = true;
  }
  abortIfOwned(): void {
    if (this.acquired && !this.closed) closeFragrantNight(this.runtime.world, this.day, "aborted");
  }
}

import type { NightStageContext, NightStageHandler } from "../../stages/night/contracts";
import { Phase } from "../../../../core/domain/identity";
import { safeRecordLogicOp } from "../../../../recording/session_recorder";
import { fragrantChoiceActor, fragrantChoiceCandidates } from "./authority";
import {
  openFragrantPairRequest,
  fragrantPairRequestScope,
  readFragrantPairTool,
  commitFragrantPairChoice,
  closeFragrantPairRequest,
} from "./requests";
import { FRAGRANT_PAIR_POLICY } from "./state";
async function execute(ctx: NightStageContext, kind: "bind" | "pair") {
  const day = ctx.currentDay(),
    actorId = fragrantChoiceActor(ctx.world, day, kind);
  if (actorId === null) return;
  const name = kind === "bind" ? "bind_fragrant_pair" : "check_pair",
    candidates = fragrantChoiceCandidates(ctx.world, day),
    request = ctx.makeRequest(actorId, [name], {
      stage: kind === "bind" ? "fragrant_bind" : "pair_inspection",
      requiresAction: true,
      allow_fallback: false,
      action_failure_policy: "error",
      ...(kind === "bind"
        ? { fragrant_pair_candidates: candidates }
        : { pair_check_candidates: candidates, ability_id: "native:pair_check" }),
    }),
    scope = openFragrantPairRequest(ctx.world, day, kind, request);
  try {
    const raw = await ctx.actionProvider.getAction(request);
    if (fragrantPairRequestScope(ctx.world, request) !== scope)
      throw Error("fragrant_request_unavailable");
    const call = readFragrantPairTool(raw);
    if (!call || call.name !== name) throw Error("fragrant_required_action_invalid");
    const valid = ctx.toolGateway.validateAndSanitize(ctx.world, actorId, call, {
      phase: Phase.Night,
      day,
      fragrantPairScope: scope,
      deferOperation: true,
    });
    if (!valid.ok || !valid.sanitizedCall || fragrantPairRequestScope(ctx.world, request) !== scope)
      throw Error("fragrant_required_action_invalid");
    const receipt = commitFragrantPairChoice(ctx.world, scope, valid.sanitizedCall);
    ctx.events.push(
      "pairIds" in receipt
        ? {
            timestamp: Date.now(),
            type: "fragrant_pair_chosen",
            payload: { policy: FRAGRANT_PAIR_POLICY, ...receipt },
            audience: Object.freeze([actorId]),
          }
        : {
            timestamp: Date.now(),
            type: "fragrant_pair_inspected",
            payload: { policy: FRAGRANT_PAIR_POLICY, ...receipt },
            audience: Object.freeze([actorId]),
          },
    );
    safeRecordLogicOp({
      scope: "gateway",
      op: "validate_tool_call",
      actorId,
      phase: Phase.Night,
      status: "ok",
      input: { tool: call.name, args: call.args },
    });
    safeRecordLogicOp({
      scope: "phase_pipeline",
      op: kind === "bind" ? "fragrant_pair_chosen" : "fragrant_pair_inspected",
      actorId,
      phase: Phase.Night,
      status: "ok",
      output: { policy: FRAGRANT_PAIR_POLICY, ...receipt },
    });
  } finally {
    closeFragrantPairRequest(scope);
  }
}
export const FRAGRANT_BIND_STAGE: NightStageHandler = {
  id: "fragrant_bind",
  priority: 150,
  execute: (ctx) => execute(ctx, "bind"),
};
export const PAIR_INSPECTION_STAGE: NightStageHandler = {
  id: "pair_inspection",
  priority: 600,
  execute: (ctx) => execute(ctx, "pair"),
};

