    day,
    closed: false,
    handedOff: false,
    delayEligible: !!alchemist && (alchemist.state() as AlchemistState).healRemaining === 1,
    lives,
    mistDecided: false,
    mistTargets: null,
    extraDecided: false,
    extra: null,
    wolfTarget: null,
    snakeRequested: false,
    snakeDecided: false,
    snakeValidating: false,
